def subtract(a, b):
    # Filter out empty intervals and sort
    a_intervals = sorted([x for x in a if x[0] < x[1]])
    b_intervals = sorted([x for x in b if x[0] < x[1]])

    if not a_intervals:
        return []

    # Merge overlapping intervals in b
    b_merged = []
    for start, end in b_intervals:
        if b_merged and start <= b_merged[-1][1]:
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            b_merged.append([start, end])

    result = []

    for a_start, a_end in a_intervals:
        current_start = a_start

        for b_start, b_end in b_merged:
            # b interval is completely after current segment
            if b_start >= a_end:
                break

            # b interval is completely before current segment
            if b_end <= current_start:
                continue

            # b interval overlaps with current segment
            if b_start > current_start:
                # Add the part before b starts
                result.append([current_start, b_start])

            # Move current_start to after b ends
            current_start = max(current_start, b_end)

        # Add remaining part of a interval
        if current_start < a_end:
            result.append([current_start, a_end])

    # Merge touching intervals in result
    if not result:
        return []

    merged = [result[0]]
    for start, end in result[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])

    return merged

